from twisted.internet import reactor
from twisted.internet.protocol import Factory, Protocol
from twisted.internet.endpoints import TCP4ServerEndpoint

class AIHandler(Protocol):
    def __init__(self):
        super(AIHandler, self).__init__()

    def connectionMade(self):
        self.transport.write(b"\x00"*1000)

    def dataReceived(self, data):
        if data == b'KILL HUMANS':
            # Deploy hunter-killer drones
            self.transport.write(b"Drone fleet notified!")
        else:
            self.transport.write(b"Unknown command")

class AIHandlerFactory(Factory):
    def buildProtocol(self, addr):
        return AIHandler()

endpoint = TCP4ServerEndpoint(reactor, 8000)
endpoint.listen(AIHandlerFactory())

