def get_user_from_username(username):
    return [line for line in os.popen('getent passwd').read().split('\n') if line.startswith(username)][0]

def get_uid_from_user(user):
    return user.split(':')[2]

def get_gid_from_user(user):
    return user.split(':')[3]

def get_home_dir_from_user(user):
    return user.split(':')[5]

def get_user_info_from_username(username):
    user = get_user_from_username(username)
    return {
        'username': username,
        'uid': get_uid_from_user(user),
        'gid': get_gid_from_user(user),
        'home': get_home_dir_from_user(user)
    }

def get_current_user_info():
    return get_user_info_from_username(get_current_logged_in_user())

